package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * When the create request opted in with {@code sharesHousehold} true, joins the new
 * owner to the household of any existing owner with the same {@code lastName} and
 * {@code address} (addresses compared in their normalized form via
 * {@link AddressNormalizer}, last names case-insensitively after collapsing whitespace —
 * the same rule that derives the shared {@code householdId} contributing to the
 * {@link OwnerIdentity} identity key).
 *
 * <p>A household is identified by a stable {@code householdId} derived from the
 * normalized lastName and address, so every member of the same household resolves to
 * the same value regardless of registration order. Both the new owner and each matched
 * existing owner are assigned that id (existing members are persisted here; the new
 * owner is persisted by the later {@link SaveOwner} step). Runs inside the create
 * transaction, so this and the new owner's save commit together.
 *
 * <p>No-ops when {@code sharesHousehold} is not true or when no matching owner exists.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request,
            OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // did not opt into sharing a household
        }
        String lastName = normalize(owner.getLastName());
        String address = AddressNormalizer.normalize(owner.getAddress());
        if (lastName == null || address == null) {
            return; // nothing to match on
        }
        List<Owner> matches = new ArrayList<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue; // never match the owner against itself
            }
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
                matches.add(existing);
            }
        }
        if (matches.isEmpty()) {
            return; // no household to join
        }
        // Reuse an existing member's id if present, otherwise derive a stable one.
        String householdId = deriveHouseholdId(lastName, address);
        for (Owner match : matches) {
            if (match.getHouseholdId() != null) {
                householdId = match.getHouseholdId();
                break;
            }
        }
        owner.setHouseholdId(householdId);
        for (Owner match : matches) {
            if (!householdId.equals(match.getHouseholdId())) {
                match.setHouseholdId(householdId);
                ownerRepository.save(match);
            }
        }
    }

    /** Stable {@code 'HH-<16 hex>'} identifier for the household keyed by lastName+address. */
    private static String deriveHouseholdId(String lastName, String address) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest((lastName + "�" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("HH-");
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02X", hash[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /** Last-name key: lower-cased, trimmed, with internal whitespace runs collapsed to one space. */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        String collapsed = value.trim().replaceAll("\\s+", " ");
        return collapsed.isEmpty() ? null : collapsed.toLowerCase(Locale.ROOT);
    }
}

